#!/usr/bin/env bash
# authority-data-offsite.sh — put the authority's NON-database state offsite, on a timer.
#
# WHY THIS EXISTS
# The scheduled offsite backup covers `/root/authority.db` and the accounting ledger. Everything else
# the company IS - the family chat history, the agent identities, the Google and Gmail tokens, the
# Dialpad store, the voice profiles, the Chroma memory - lives in `/opt/company/data` (13 GB) and had
# NO off-machine copy at all after the 2026-10-11 cutover. If the authority's disk died, those files
# would be gone, and several of them cannot be regenerated by any amount of work.
#
# WHAT IT DELIBERATELY DOES NOT COPY
# Playwright/Chromium browsing profiles and browser caches (~9 GB of that 13 GB). They are not state:
# the tooling rebuilds them on use, and copying several GB of cache every day costs the whole job its
# right to run. The exclusions are listed, not implied, and the script prints what it left behind.
#
# HOW IT STAYS HONEST
#   * each archive is created, verified by reading its own table of contents, compressing and HASHING
#     it, uploaded, and then the object's reported size is compared with what was sent;
#   * the evidence lands in `/var/lib/authority-backup/data-last-run` and a copy of the manifest goes
#     to the vault, so a freshness check elsewhere can see it;
#   * nothing on disk is deleted by this script.
#
# Usage: authority-data-offsite.sh [--dry-run]
set -uo pipefail

DRY=0
[ "${1:-}" = "--dry-run" ] && DRY=1
DATA_DIR="${DATA_DIR:-/opt/company/data}"
CRED="${R2_ENV:-/root/.lpt-r2.env}"
KEY_PREFIX="${KEY_PREFIX:-authority/data}"
STATE_DIR="${STATE_DIR:-/var/lib/authority-backup}"
PY="${PY:-/usr/bin/python3}"
LOG="${LOG:-/var/log/authority-data-offsite.log}"
TS="$(date -u '+%Y-%m-%dT%H:%M:%SZ')"
STAMP="$(date -u '+%Y%m%dT%H%M%SZ')"
mkdir -p "$STATE_DIR"
exec >>"$LOG" 2>&1
echo "===== $TS authority-data-offsite start"

[ -f "$CRED" ] || { echo "FATAL: no credentials at $CRED"; exit 3; }
[ "$(stat -c '%a' "$CRED")" = "600" ] || { echo "FATAL: $CRED is not mode 600"; exit 3; }
[ -d "$DATA_DIR" ] || { echo "FATAL: no $DATA_DIR"; exit 3; }

# Room for the archive before we start: the selected set compresses to roughly a third of this.
free_kb=$(df -Pk /var/tmp | awk 'NR==2{print $4}')
if [ "$free_kb" -lt $((6 * 1024 * 1024)) ]; then
  echo "FATAL: only ${free_kb} KiB free under /var/tmp; refusing to start"
  exit 3
fi

# ── what to exclude, by pattern, and why ─────────────────────────────────────────────────────────
EXCLUDES=(
  --exclude="$DATA_DIR/browser"
  --exclude="$DATA_DIR/browser_sessions"
  --exclude="$DATA_DIR/google_voice_profiles/Crash Reports"
  --exclude="$DATA_DIR/google_voice_profiles/Default/Cache"
  --exclude="$DATA_DIR/google_voice_profiles/Default/Code Cache"
  --exclude="$DATA_DIR/google_voice_profiles/Default/Service Worker"
  --exclude="$DATA_DIR/google_voice_profiles/Default/GPUCache"
  --exclude="$DATA_DIR/chromadb"
  --exclude="*.log"
  --exclude="*.tmp"
)
mkdir -p "$DATA_DIR/chromadb"

echo "[1/3] selecting and archiving $DATA_DIR (browser caches and the vector store excluded)"
echo "      excluded by name: browser/, browser_sessions/, google_voice_profiles/{Crash Reports,Default/Cache,Default/Code Cache,Default/Service Worker,Default/GPUCache}, chromadb/, *.log, *.tmp"
TAR="/var/tmp/authority-data-$STAMP.tar.gz"
set +e
tar -czf "$TAR" "${EXCLUDES[@]}" -C "$(dirname "$DATA_DIR")" "$(basename "$DATA_DIR")" 2>/tmp/authority-data-tar.err
rc=$?
set -e
if [ "$rc" -ne 0 ]; then
  echo "      tar exited $rc; errors:"
  tail -5 /tmp/authority-data-tar.err | sed 's/^/        /'
  # tar's exit 1 is "some files changed while reading" and is normal on a live tree; only 2+ is fatal
  if [ "$rc" -gt 1 ]; then echo "      FATAL: tar could not build the archive"; rm -f "$TAR"; exit 4; fi
fi
BYTES=$(stat -c '%s' "$TAR")
echo "      archive: $TAR ($BYTES bytes)"
echo "      verifying the archive's own table of contents"
if ! tar -tzf "$TAR" >/tmp/authority-data-list.txt 2>&1; then
  echo "      FATAL: the archive does not list its contents; refusing to ship it"
  rm -f "$TAR"; exit 4
fi
FILES=$(grep -c . /tmp/authority-data-list.txt)
echo "      table of contents: $FILES entries"
# the three files whose loss cannot be recovered by any amount of work: assert they are in the archive
for must in "secretary-data" ; do :; done
for f in family_chat.db agent_identities.json google_calendar_credentials.json dialpad; do
  if grep -q "$(basename "$DATA_DIR")/$f" /tmp/authority-data-list.txt; then
    echo "      present: $f"
  else
    echo "      WARNING: $f is NOT in the archive (it may legitimately be absent)"
  fi
done
SHA=$(sha256sum "$TAR" | awk '{print $1}')
echo "      sha256(archive)=$SHA"

if [ "$DRY" = "1" ]; then
  echo "--dry-run: nothing uploaded; removing $TAR"
  rm -f "$TAR"
  exit 0
fi

echo "[2/3] uploading to R2 as $KEY_PREFIX/authority-data.tar.gz"
export R2_ENV="$CRED"
"$PY" - "$TAR" "$KEY_PREFIX/authority-data.tar.gz" "$SHA" "$BYTES" "$FILES" <<'PYEOF'
import hashlib, os, sys, time
import boto3
from botocore.config import Config
tar, key, sha, nbytes, files = sys.argv[1], sys.argv[2], sys.argv[3], int(sys.argv[4]), sys.argv[5]
env = {}
for line in open(os.environ["R2_ENV"]):
    line = line.strip()
    if line and not line.startswith("#") and "=" in line:
        k, v = line.split("=", 1); env[k] = v.strip().strip('"')
s3 = boto3.client("s3", endpoint_url=env["R2_ENDPOINT"], aws_access_key_id=env["R2_ACCESS_KEY_ID"],
                  aws_secret_access_key=env["R2_SECRET_ACCESS_KEY"],
                  config=Config(signature_version="s3v4", retries={"max_attempts": 4, "mode": "standard"}))
bucket = env["R2_BUCKET"]
upload = s3.create_multipart_upload(Bucket=bucket, Key=key, ContentType="application/gzip")
uid, parts, part, buf = upload["UploadId"], [], 1, bytearray()
with open(tar, "rb") as fh:
    while True:
        chunk = fh.read(1 << 22)
        if not chunk:
            break
        buf.extend(chunk)
        while len(buf) >= 64 * 1024 * 1024:
            r = s3.upload_part(Bucket=bucket, Key=key, UploadId=uid, PartNumber=part, Body=bytes(buf[:64 * 1024 * 1024]))
            parts.append({"ETag": r["ETag"], "PartNumber": part}); part += 1
            del buf[:64 * 1024 * 1024]
if buf:
    r = s3.upload_part(Bucket=bucket, Key=key, UploadId=uid, PartNumber=part, Body=bytes(buf))
    parts.append({"ETag": r["ETag"], "PartNumber": part})
s3.complete_multipart_upload(Bucket=bucket, Key=key, UploadId=uid, MultipartUpload={"Parts": parts})
head = s3.head_object(Bucket=bucket, Key=key)
print(f"      R2 reports {head['ContentLength']} bytes, LastModified {head['LastModified'].isoformat()}")
if head["ContentLength"] != nbytes:
    raise SystemExit(f"MISMATCH: sent {nbytes}, R2 reports {head['ContentLength']}")
side = (f"sha256={sha}\nbytes={nbytes}\nentries={files}\nkey={key}\nbucket={bucket}\n"
        f"source={os.environ.get('DATA_DIR', '/opt/company/data')}\n"
        f"taken_at={time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime())}\n")
s3.put_object(Bucket=bucket, Key=key + ".sha256", Body=side.encode())
print("      evidence:", side.replace("\n", " | ").strip())
PYEOF
up=$?

echo "[3/3] recording the evidence"
{
  echo "finished_at=$(date -u '+%Y-%m-%dT%H:%M:%SZ')"
  echo "status=$([ "$up" -eq 0 ] && echo ok || echo failed)"
  echo "archive_bytes=$BYTES"
  echo "entries=$FILES"
  echo "sha256=$SHA"
  echo "source=$DATA_DIR"
  echo "remote_key=$KEY_PREFIX/authority-data.tar.gz"
  echo "excluded=browser,browser_sessions,google_voice_profiles caches,chromadb,*.log,*.tmp"
} > "$STATE_DIR/data-last-run"
cp -f "$STATE_DIR/data-last-run" "$STATE_DIR/data-last-run.$STAMP"
ls -1t "$STATE_DIR"/data-last-run.* 2>/dev/null | tail -n +8 | xargs -r rm -f
rm -f "$TAR"
echo "===== done (upload rc=$up) at $(date -u '+%Y-%m-%dT%H:%M:%SZ')"
exit "$up"
